import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../core/app_colors.dart';
import '../providers/obd_provider.dart';

class VehicleHealthScoreScreen extends StatelessWidget {
  const VehicleHealthScoreScreen({super.key});
  @override Widget build(BuildContext context){final o=context.watch<ObdProvider>();final h=_Health.from(o);return Scaffold(backgroundColor:AppColors.background,appBar:AppBar(backgroundColor:AppColors.background,foregroundColor:Colors.white,title:const Text('ARAÇ SAĞLIK SKORU',style:TextStyle(fontWeight:FontWeight.w900))),body:ListView(padding:const EdgeInsets.fromLTRB(16,8,16,28),children:[
    Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(gradient:const LinearGradient(colors:[Color(0xFF281013),Color(0xFF111214)]),borderRadius:BorderRadius.circular(22),border:Border.all(color:AppColors.accentBorder)),child:Column(children:[Text('%${h.score}',style:TextStyle(color:h.color,fontSize:54,fontWeight:FontWeight.w900,letterSpacing:-2)),Text(h.label,style:TextStyle(color:h.color,fontSize:13,fontWeight:FontWeight.w900)),const SizedBox(height:5),Text('${o.detectedBrand??'Araç'} • ${o.detectedVin??'VIN yok'}',style:const TextStyle(color:Colors.white38,fontSize:9.5))])),
    const SizedBox(height:12),Row(children:[Expanded(child:_ScoreBox('KRİTİK',h.critical,AppColors.danger)),const SizedBox(width:8),Expanded(child:_ScoreBox('ORTA',h.medium,AppColors.warning)),const SizedBox(width:8),Expanded(child:_ScoreBox('BİLGİ',h.info,AppColors.info))]),
    const SizedBox(height:16),const Text('SKORU ETKİLEYENLER',style:TextStyle(color:AppColors.textMuted,fontSize:10,fontWeight:FontWeight.w900,letterSpacing:.8)),const SizedBox(height:8),
    ...h.reasons.map((e)=>Container(margin:const EdgeInsets.only(bottom:8),padding:const EdgeInsets.all(13),decoration:BoxDecoration(color:AppColors.cardBg,borderRadius:BorderRadius.circular(15),border:Border.all(color:e.$3.withValues(alpha:.2))),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(e.$1,color:e.$3,size:19),const SizedBox(width:9),Expanded(child:Text(e.$2,style:const TextStyle(color:Colors.white70,fontSize:10.5,height:1.4)))]))),
    const SizedBox(height:8),ElevatedButton.icon(onPressed:!o.canQueryDtc||o.isFullScanning?null:()=>context.read<ObdProvider>().runFullVehicleScan(),icon:o.isFullScanning?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2,color:Colors.white)):const Icon(Icons.health_and_safety_rounded),label:Text(o.isFullScanning?'TARAMA YAPILIYOR...':'SAĞLIK TARAMASINI YENİLE',style:const TextStyle(fontWeight:FontWeight.w900))),
    const SizedBox(height:10),const Text('Bu skor bakım/servis kararının yerine geçmez; ECU DTC’leri, readiness ve ölçülebilen canlı verilerden açıklanabilir bir özet üretir.',style:TextStyle(color:Colors.white30,fontSize:9,height:1.4)),
  ]));}
}
class _ScoreBox extends StatelessWidget{const _ScoreBox(this.label,this.value,this.color);final String label;final int value;final Color color;@override Widget build(BuildContext context)=>Container(padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:color.withValues(alpha:.07),borderRadius:BorderRadius.circular(14),border:Border.all(color:color.withValues(alpha:.2))),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label,style:const TextStyle(color:Colors.white38,fontSize:7,fontWeight:FontWeight.w900)),const SizedBox(height:3),Text('$value',style:TextStyle(color:color,fontSize:20,fontWeight:FontWeight.w900))]));}
class _Health{final int score,critical,medium,info;final List<(IconData,String,Color)> reasons;const _Health(this.score,this.critical,this.medium,this.info,this.reasons);String get label=>score>=90?'ÇOK İYİ':score>=75?'İYİ':score>=55?'KONTROL GEREKİYOR':'SERVİS ÖNERİLİR';Color get color=>score>=90?AppColors.success:score>=75?AppColors.info:score>=55?AppColors.warning:AppColors.danger;static _Health from(ObdProvider o){var score=100,crit=0,med=0,info=0;final r=<(IconData,String,Color)>[];final stored=o.dtcEntries.where((e)=>e.status==DtcStatus.stored).length;final pending=o.dtcEntries.where((e)=>e.status==DtcStatus.pending).length;final permanent=o.dtcEntries.where((e)=>e.status==DtcStatus.permanent).length;if(stored>0){score-=stored*12;crit+=stored;r.add((Icons.error_rounded,'$stored kayıtlı DTC bulundu.',AppColors.danger));}if(pending>0){score-=pending*6;med+=pending;r.add((Icons.schedule_rounded,'$pending bekleyen DTC bulundu.',AppColors.warning));}if(permanent>0){score-=permanent*4;med+=permanent;r.add((Icons.lock_clock_rounded,'$permanent kalıcı DTC ECU koşulları tamamlanana kadar izlenmeli.',AppColors.warning));}if(o.milOn==true){score-=8;crit++;r.add((Icons.warning_amber_rounded,'Arıza lambası (MIL) ECU tarafından aktif bildiriliyor.',AppColors.danger));}if(o.readiness.supported>0&&o.readiness.incomplete.isNotEmpty){final p=o.readiness.incomplete.length.clamp(1,4).toInt();score-=p*3;info++;r.add((Icons.fact_check_outlined,'Readiness monitörlerinin tamamı hazır değil.',AppColors.info));}if(o.data.engineTemp>110){score-=12;crit++;r.add((Icons.device_thermostat_rounded,'Soğutma suyu sıcaklığı yüksek: ${o.data.engineTemp} °C.',AppColors.danger));}if((o.oilTempC??0)>125){score-=8;med++;r.add((Icons.oil_barrel_rounded,'Yağ sıcaklığı yüksek: ${o.oilTempC} °C.',AppColors.warning));}final v=o.controlModuleVoltage??o.data.voltage;if(v>0&&o.data.rpm>500&&(v<13.2||v>15)){score-=7;med++;r.add((Icons.battery_alert_rounded,'Şarj voltajı normal aralığın dışında: ${v.toStringAsFixed(1)} V.',AppColors.warning));}if(r.isEmpty){info++;r.add((Icons.verified_rounded,'Mevcut taramada skoru düşüren ölçülebilir bir bulgu yok.',AppColors.success));}return _Health(score.clamp(0,100).toInt(),crit,med,info,r);}}
